-- seed-catalog.sql — 크롤러 카탈로그의 현실 부분집합 시드 (dev 스냅샷 유래)
--
-- 무엇: sido·sigungu·job_group·job_role 는 전체, company·job_posting·job_posting_role 는
--       "게시 공고가 많은 상위 40개사 × 회사별 최근 공고 최대 2건 + 그 직무 매핑"으로 추린 부분집합.
--       실제 회사·공고(쿠팡·CJ올리브영·우아한형제들·토스뱅크 …)라 FE 목록·검색·상세를 현실감 있게 개발할 수 있다.
--       id 는 dev 원본 값을 그대로 보존해 표 사이 참조(company_id·job_posting_id·job_role_id)가 맞아떨어진다.
--
-- 어디에: seed.sql(합성 최소 시드, 고정 id 1~6)과 별개다. 이 파일은 H2 테스트에 싣지 않는다.
--   ⚠️ 두 시드를 같은 DB 에 함께 적재하면 안 된다 — 참조 테이블 id 범위가 겹친다
--      (실데이터 job_group 1~25·job_role 1~296·sido 1~16·sigungu 1~230 vs seed.sql 의 1~6).
--   대상은 MySQL 8 의 "비어 있는 카탈로그"다: schema.sql 로 표를 만든 뒤 이 파일만 적재한다.
--     - dev RDS 재생성 시 재시드
--     - 합성 대신 현실 데이터로 돌리고 싶은 로컬 MySQL (seed.sql 대신 이 파일을 로드)
--   적용 예: mysql --host=127.0.0.1 --port=13306 -u<user> -p moimyeondev < seed-catalog.sql
--
-- 원천: dev RDS(moimyeondev) 스냅샷. 전체(모든 행)는 커밋하지 않고 로컬에 둔다(.local/seed-catalog-full.sql).
-- 갱신: 크롤러가 데이터를 바꾸면 스냅샷을 다시 떠 이 파일을 재생성한다
--       (기본 워크트리의 .local/gen_seed.py — DB 접속정보를 담아 커밋하지 않는 로컬 전용 스크립트).
SET NAMES utf8mb4;

