-- job_posting — 선정 회사별 최근 공고 최대 2건 (80 rows)
INSERT INTO job_posting (id, source_uid, company_id, title, regions, career_min, career_max, employee_types, educations, posted_at, end_date, deadline_type, is_open, source_url, redirect_url, summary, content, created_at, updated_at, deleted_at, verified, created_by_member_id) VALUES
  (2029, 'e207eb1a-d6ea-4da5-b0da-3a6edcd13485', 78606, '그로스 플랫폼 프로덕트 빌더', '경기', 5, 100, '정규직', '무관', '2026-07-14 21:05:04', NULL, '상시채용', 1, 'https://zighang.com/recruitment/e207eb1a-d6ea-4da5-b0da-3a6edcd13485', 'https://www.wanted.co.kr/wd/374934?client_id=ubRphx9ewFwQvQV3kyJjjFSp', NULL, '소개
카카오페이증권은 어렵고 복잡한 투자의 문턱을 낮추고,
생활 속 가장 가까운 금융투자 회사를 만듭니다.
국내최초 테크핀 증권사에서 새로운 투자문화를 함께 만들어 갈 여러분을 기다립니다.

주요업무
• 그로스플랫폼팀의 로드맵을 정의하고, 서비스의 성장 가설을 실험 단위로 쪼개 우선순위를 정해요.
 • AI 도구로 기획안 · UX · PoC · 실제 구현까지 한 사이클을 직접 끝내요. 기획  화면  시스템 사이의 핸드오프 비용을 없애요.
 • 다양한 그로스 제품을 직접 설계하고 만들어 전사 구성원이 사용하게 해요.
 • 사용자 획득 · 온보딩 · 리텐션 플로우의 서비스 API와 프론트엔드 컴포넌트를 직접 구현해 가설을 빠르게 화면으로 옮겨요.
 • 행동 로그 · 지표 정의서 · 실험 가이드 · OKR을 팀의 자산으로 정비해, 다음 사이클이 더 빨리 돌도록 만들어요.
 • 프로덕트/마케팅의 가설을 즉시 실행 가능한 실험 단위로 변환해요.

자격요건
• 그로스 · 프로덕트 · 엔지니어링 영역에서 합산 경력 5년 이상의 실무 경험을 보유하고, 한 영역에 머무르지 않고 경계를 넘나든 경험이 있으신 분을 원해요. (예: PM 출신이지만 직접 PoC · 코드를 작성해온 분/풀스택 엔지니어이지만 직접 프로덕트 의사결정을 주도해온 분/ 창업 · 인디 해커 경험자 등)
• 백엔드 개발 · 프론트엔드 개발 · 프로덕트 매니지먼트 중 최소 한 영역에서 시니어 수준의 깊이(설계 · 구현 · 운영을 주도해본 경험)를 갖추신 분으로, 다른 영역들은 AI 도구를 활용해 결과물을 완성할 수 있어야 해요. 모든 영역을 직접 깊게 경험하지 않아도 돼요.
• Claude Code · Cursor · Codex 등 AI 개발 도구를 일상 워크플로우의 핵심으로 사용하며, 본인이 익숙하지 않은 영역(FE/SQL/디자인/기획 등)도 AI와 함께 결과물을 완성해본 구체적 경험이 있으신 분을 원해요.
• AI가 만든 결과물의 품질을 본인이 판단하고, 부족한 부분을 직접 보완할 수 있는 분을 원해요. 단순 기능 구현이 아닌 문제 정의  설계  검증까지 주도해요.
• 본인의 깊이 영역에서는 AI 출력물을 교정할 수 있어야 하고, 그 외 영역에서는 빠르게 학습해 결과물을 검증할 수 있어야해요.
• 사용자 가설을 PRD · 화면 · 실험 단위로 변환하고, 실험 결과를 비즈니스 의사결정에 연결해본 경험이 있으신 분을 원해요.

우대사항
• 창업 경험 · 인디 해커 경험 · 1인 개발자 경험 등 한 사람이 사이클 전체를 끝내본 경험이 있으신 분이면 좋아요.
• 팀 내 AI 활용 워크플로우 · 프롬프트 · 플레이북을 자산화하고 전파해본 경험이 있으신 분이면 좋아요.
• 행동 로그 설계 · 지표 정의 · 실험 가이드 등 그로스 운영 자산을 정비해본 경험이 있으신 분이면 좋아요.
• Amplitude · Mixpanel · Braze 등 그로스 분석/마케팅 자동화 툴 활용 경험이 있으신 분이면 좋아요.
• 관측성 도구(OpenTelemetry · Grafana · OpenSearch · Sentry 등)로 실험 결과와 서비스 지표를 분석·개선해본 경험이 있으신 분이면 좋아요.
• 핀테크 또는 금융(증권 · 투자) 도메인 경험이 있으신 분이면 좋아요.

