삼양식품은 1961년 창립 이래, 1963년 한국 최초 인스턴트 라면을 선보이며 식품 산업을 선도해 왔습니다. 라면을 포함해 스낵, 소스, HMR 등 다양한 제품군으로 확장하며 종합 식품 기업으로 성장해왔습니다.

국내뿐 아니라 미국·중국·유럽 등 주요 해외 시장에 판매 법인을 운영하며 글로벌 네트워크를 구축하여 안정적인 생산 체계를 확보했습니다. 더불어 삼양식품은 변화하는 글로벌 식품 시장과 소비자 트렌드에 민첩하게 대응하며, 혁신적인 제품 개발과 브랜드 확장을 이어가고 있습니다.

세계 시장을 무대로 경쟁하고 성장하는 글로벌 식품 기업으로서, 앞으로의 더 큰 가능성을 함께 만들어갈 인재를 기다립니다.

주요업무
삼양식품은 글로벌 비즈니스 전반에 AI 기술을 특화 적용하고, 0 to 1 단계부터 전사 AX(AI Transformation) 체계를 주도적으로 정립하기 위해 AX전담 부서를 신설했습니다.

그 중 데이터인텔리전스팀은 AI 시대의 핵심 자산인 데이터를 신뢰할 수 있는 형태로 표준화하고, 이를 기반으로 비즈니스 프로세스를 지능화하는 조직입니다.

전사 데이터 거버넌스 체계를 새롭게 정립하여, 경영진과 현업이 실시간 데이터를 바탕으로 의사결정(Data-driven Decision)을 내릴 수 있는 기반을 구축하며, 데이터를 통해 실질적인 비즈니스 개선 방안을 도출하고 변화를 이끌어갈 분을 모시고 있습니다.

• 전사 데이터 표준 및 품질 관리 체계를 구축하고 안정적인 운영 프로세스를 리딩합니다.
• 업무 도메인별 데이터 과제를 발굴하고 실증(PoC) 프로세스를 총괄 관리합니다.
• 데이터 및 AI 관점의 업무 분석을 통해 전사 적용 영역을 도출하고 개선 방안을 설계합니다.
• 현업 요구사항을 데이터/AI 과제로 구체화하고, 구현 조직과의 협업 체계를 조율합니다.
• 전사 데이터 인벤토리 구축과 데이터 품질의 지속적인 개선 활동을 주도합니다.

자격요건
• 총 경력 15년 이상 선호 (유관 경력 10년 이상 지원 가능)
• 데이터 관리, 분석 실무 또는 현업 도메인(생산/SCM/영업 등) 실무를 기반으로 팀을 이끌어본 경험이 있는 분
• SQL 등 데이터 조회 및 분석 기본 역량을 바탕으로, 비즈니스와 데이터 구조를 연결하는 시야를 가진 분
