All Live Better,

No.1 헬스&뷰티 스토어 올리브영은 20년 이상 축적된 경험과 데이터, 협력 체계를 바탕으로 이제는 국내를 넘어 글로벌 시장을 리딩하는 라이프스타일 플랫폼이자 새로운 옴니채널 사업자로 진화하고 있습니다.

올리브영은 앞으로도 끊임없이 변화하고 혁신하며 전 세계인의 건강한 아름다움을 큐레이팅하는 ''글로벌 No.1 옴니채널 라이프스타일 플랫폼''을 향한 비전을 달성할 것입니다.

올리브영의 독보적인 오프라인 비즈니스를 기반으로 온라인 서비스를 결합하여 온·오프의 경계를 허무는 End-to-End 플랫폼을 함께 만들어가실 역량 있는 분을 모십니다.

주요업무
올리브영 AD프로덕트팀은
올리브영의 ​온·오프라인 ​미디어 ​생태계를 기반으로 ​리테일미디어 사업의 광고 상품을 ​구현하고,
이를 ​효율적으로 집행·운영할 ​수 있는 광고 ​플랫폼의 기획·운영·고도화를 ​담당하고 ​있습니다.

AD프로덕트팀 PM은 ​올리브영 ​리테일미디어의 ​광고 상품과 광고 ​플랫폼을 ​담당하며,
광고 성과·사용자 경험·운영 ​효율을 ​종합적으로 ​고려해
광고 프로덕트를 지속적으로 ​개선·확장하는 역할을 ​수행합니다.

[주요 ​업무]
① 유관 ​부서(사업·개발·데이터) 및 ​외부 ​파트너 요구사항 분석 ​및 협업을 ​통한 서비스 구체화
② 올리브영 데이터플랫폼 설계 및 운영 정책 수립
③ 오디언스 타겟팅, BI, 리포트 등 데이터 플랫폼 기능 기획 및 고도화
④ 오프사이트 미디어 및 외부 솔루션 연동을 통한 서비스 구축 및 확장

