[포지션] Mnet Plus 콘텐츠 전략(Acquisition Part)

[직무 개요] 
본 포지션은 플랫폼 고유의 아이덴티티를 완성할 수 있는 차별화된 콘텐츠 라인업을 독립적으로 구축하는 역할입니다. 강력한 자사 제작사의 Captive 콘텐츠 및 오리지널 라인업을 축으로 삼되, 이와 시너지를 낼 수 있는 K-POP, 디지털 숏폼, 트렌디한 예능 등 다양한 포맷의 외부 콘텐츠를 발굴하고 수급(Acquisition)하는 전략적 핵심 포지션입니다.

주요업무
• 플랫폼 맞춤형 수급을 위한 전략과 실행안 수립: 자사 오리지널 및 Captive 콘텐츠(Mnet, KCON 등) 라인업과의 시너지를 고려한 외부 콘텐츠 포트폴리오 기획 및 소싱
• 디지털 & K-POP 콘텐츠 소싱: 디지털 콘텐츠 제작사, MCN, 엔터테인먼트사 등과의 파트너십을 통해 플랫폼 타겟에 최적화된 트렌디한 콘텐츠 확보
• 수급 밸류체인 전반 리딩: 제안, 조건 협상, 계약서 검토, 정산 및 사후 관리까지 수급 프로세스 전반을 독립적으로 책임지고 실행
• 데이터 기반 효율성 관리: 배정된 예산 내에서 콘텐츠별 시청 지표 및 유입 기여도를 분석하여, 롱테일(Long-tail) 및 버티컬 콘텐츠의 효율(ROI) 극대화

자격요건
• 경력: OTT, 방송사, 디지털 콘텐츠 제작사, MCN, 엔터테인먼트사 등에서 콘텐츠 수급/유통/라이선싱 경력 만 6년 이상 혹은 그에 준하는 역량을 보유하신 분
• 트렌드 인사이트: K-POP 및 디지털 미디어 생태계에 대한 깊은 이해도를 바탕으로, 팬덤 및 MZ 타겟을 움직이는 콘텐츠를 알아보는 선구안을 가진 분
• 네트워크: 국내 주요 디지털 콘텐츠 제작사, 뉴미디어 플랫폼, 주요 연예 기획사(엔터사) 등과의 견고한 인적 네트워크 보유자
• 독립적 직무 수행 능력: 명확한 오너십을 바탕으로 거시적 라인업 전략 수립부터 계약서 조항 검토, 판권 정산 등 실무적 디테일까지 책임지고 완결할 수 있는 분

우대사항
• K-POP 아이돌 기반 예능, 웹드라마, 미드폼/숏폼 콘텐츠 수급 또는 제작 참여 경험자
• 자사 IP(Captive/오리지널)와 연계한 외부 콘텐츠 패키징/편성 다각화 경험자
• 미디어 라이선스 관련 법률(저작권, 초상권, 글로벌 판권 범위 등)에 대한 전문적 이해도 보유자

[캐릭터&성향]
• 직군과 관계없이 어울릴 수 있고, 적극적인 커뮤니케이션을 하려고 노력하는 분
• 우선순위를 명확히 하여 Resource 대비 최대의 Impact를 만들어 줄 수 있는 분
• 나의 팀만을 위한 의사결정이 아닌 사업부 차원의 의사결정을 할 수 있는 분
• 사업과 조직의 Stage변화에 맞춰 유연하게 사고하고, 일하는 방법과 Role, Formation 방식 등에 유연하게 대응할 수 있는 분
• 콘텐츠에 대한 진심과 애정으로 콘텐츠業을 사랑하며 진정한 덕업일치를 이루고 싶은 분

