"Style My CONCEPT"

W CONCEPT은 스타일의 새로운 관점을 제공하여, 
누구나 자신만의 스타일을 탐구하고 취향의 저변을 넓혀갈 수 있는 경험을 제공하기 위해 
존재합니다.

W CONCEPT은 한계에 안주하지 않고 고객과 브랜드의 필요에 귀 기울이며 
더 큰 만족을 위해 노력하고 있습니다.
이렇듯 끈기 있게 새로운 것에 도전하는 태도는 
W CONCEPT을 앞으로 나아가게 하는 원동력이 됩니다.

W CONCEPT은 2006년부터 국내 신진 디자이너 브랜드 소개를 시작으로 
다양한 상품과 브랜드를 발굴 해왔습니다.
W CONCEPT의 안목으로 선별된 브랜드는 감각적인 큐레이션을 통해 세상에 알려지고 
더 많은 사람에게 사랑 받습니다.
이러한 일련의 작업은 오늘과 내일, 올해와 내년에도 한결같이 이어지며
국내 패션 시장의 변화, 나아가 글로벌 패션 시장에서의 K-디자이너 브랜드의 명성을 
높이기 위해 꾸준히 나아가고 있습니다.

W CONCEPT은 신세계 그룹 계열사로, 2021년 5월 SSG.COM의 자회사로 합류하였으며
패션, 뷰티, 라이프스타일 전반의 카테고리 확장과 관계사와의 협업을 통해 패션 플랫폼의 강자로 시장을 선도해나가고 있습니다.

공고에서 다루지 못한 W컨셉의 이야기가 궁금하시다면 W컨셉 채용 홈페이지를 방문 해주세요 :D

주요업무
[잡화팀 소개]
잡화팀은 백, 슈즈, 주얼리 등 다양한 잡화 카테고리의 감도 높은 브랜드 큐레이션과 
차별화된 셀렉션 운영을 통해 고객에게 새로운 패션 라이프스타일을 제안하는 팀이에요.
국내외 디자이너 브랜드의 발굴부터 입점 협상, 단독 상품 기획, 매출 성장 전략까지 
전 과정을 주도적으로 수행하며, MD로서의 커리어를 빠르게 확장할 수 있어요! 
잡화팀과 함께 카테고리를 함께 키워나갈 동료를 찾고 있어요!

[주요업무]
• 카테고리 전반의 매출 및 손익 관리, KPI 설정 및 성과 분석을 통한 성장 전략 수립 및 실행
• 트렌드 기반 브랜드 및 상품 운영 전략 기획 (신규 입점, 브랜드 육성, 포트폴리오 리밸런싱 포함)
• 데이터 분석을 기반으로 주요 브랜드와의 협업을 통한 GMV 확대 전략 수립 및 실행
• 유관부서와의 긴밀한 협업을 통한 프로모션/캠페인 기획 및 실행
• 신규 브랜드 발굴 및 온보딩 전략 수립을 통한 셀렉션 구축 및 카테고리 경쟁력 강화
• 화제성 있는 이슈 및 단독 상품 기획 주도를 통한 차별화 실현

자격요건
[자격요건]
• 유관 경력 3년 이상 7년 이
• 데이터 활용 능력이 우수하신 분
• 패션 이커머스 환경에서 잡화 카테고리/브랜드 운영 경력이 있으신 분
• 데이터 기반의 세일즈 전략을 수립 및 실행이 가능하신 분
• 국내외 잡화·가방 브랜드 네트워크 또는 소싱 경험을 보유하신 분
• 패션 트렌드/이커머스 시장에 대한 높은 이해도와 빠른 학습/적용 능력을 갖추고 있으신 분

우대사항
[우대사항]
• 여성잡화 카테고리 운영 경험을 보유하신 분
