"Style My CONCEPT" 

W CONCEPT은 스타일의 새로운 관점을 제공하여, 
누구나 자신만의 스타일을 탐구하고 취향의 저변을 넓혀갈 수 있는 경험을 제공하기 위해 
존재합니다.

W CONCEPT은 한계에 안주하지 않고 고객과 브랜드의 필요에 귀 기울이며 
더 큰 만족을 위해 노력하고 있습니다.
이렇듯 끈기 있게 새로운 것에 도전하는 태도는 
W CONCEPT을 앞으로 나아가게 하는 원동력이 됩니다.

W CONCEPT은 2006년부터 국내 신진 디자이너 브랜드 소개를 시작으로 
다양한 상품과 브랜드를 발굴 해왔습니다.
W CONCEPT의 안목으로 선별된 브랜드는 감각적인 큐레이션을 통해 세상에 알려지고 
더 많은 사람에게 사랑 받습니다.
이러한 일련의 작업은 오늘과 내일, 올해와 내년에도 한결같이 이어지며
국내 패션 시장의 변화, 나아가 글로벌 패션 시장에서의 K-디자이너 브랜드의 명성을 
높이기 위해 꾸준히 나아가고 있습니다.

W CONCEPT은 신세계 그룹 계열사로, 2021년 5월 SSG.COM의 자회사로 합류하였으며
패션, 뷰티, 라이프스타일 전반의 카테고리 확장과 관계사와의 협업을 통해 패션 플랫폼의 강자로 시장을 선도해나가고 있습니다.

공고에서 다루지 못한 W컨셉의 이야기가 궁금하시다면 W컨셉 채용 홈페이지를 방문 해주세요 :D

주요업무
[KAM팀 Sales파트 소개]
KAM(; Key Account Management)팀은 국내 · 해외 패션/유통 시장 내 Key 브랜드 및 라이징 브랜드를 담당하는 팀이에요.
특히 Sales파트는 브랜드 발굴 및 입점, Sales 육성/관리까지 업무 전반에 걸친 주도적인 기획력을 발휘하고 있어요.
브랜드와의 다양한 협업을 통해 커리어 성장(단독 상품 개발, 신규 컨텐츠 기획 및 참여)이 가능해요!
적극적이고 자유롭게 소통하며, 회사와 개인의 성장을 함께하는 자유롭고 협력적인 분위기를 가진 KAM팀 Sales파트의 동료가 되어주실 분을 찾고 있어요!

[주요업무]
• 여성 컨템포러리/잡화 카테고리(여성,남성,키즈,스포츠,해외) 내 브랜드 발굴 및 입점 영업 업무 수행
• 주간/월간 단위로 시장 트렌드 파악 및 소싱 타켓 선정
• 네트워크 및 영업력을 강화를 통한 협력사의 커뮤니케이션 및 이슈 현황 파악
• Sales 확대를 위한 효율적인 프로모션 방안 수립 및 운영

자격요건
[자격요건]
