[조직소개]
배달의민족은 외식업 사장님들이 가게 운영을 더 잘할 수 있도록 2014년부터 배민아카데미 프로그램을 운영하며 사장님의 성장을 지원하고 있습니다.
가게를 운영하는 데 필요한 지식을 포함하여 외식 경영 이론부터 쿠킹 클래스, 메뉴 개발까지 다양한 교육을 무료로 제공하고 있습니다.
가게 운영에 늘 바쁜 외식업 사장님들이 편리하게 교육에 참여하실 수 있도록 서울센터와 경기센터의 오프라인 교육뿐만 아니라, 배민아카데미 사이트를 통해 쉽게 이용하실 수 있는 비대면 교육 확대에도 힘쓰고 있습니다.
교육에는 외식업 종사자와 예비창업자는 물론 일반인도 참여할 수 있으며, 배움을 통해 꿈꾸고 성장하려는 분들을 위해 준비하고 있습니다.
배민아카데미는 외식업 사장님의 배움에 늘 함께합니다.

