직무 Summary 

담당 BU의 사업목표 달성을 위해 전사 HR 정책과 담당 BU를 연계하여 통합적 관점에서 채용, 보상, 성과관리, 인재관리, 변화관리 등 구성원 life cycle 전반에 걸친 인사제도를 실행합니다. BU 사업에 대한 깊이 있는 이해를 바탕으로, 담당 BU뿐만 아니라 전사 이해관계자 (경영진, 피플 조직)의 서로 다른 이해와 니즈를 파악하고 조율하여 최적의 솔루션을 제안합니다. 이 과정에서 전사 HR의 방향성과 정책을 명확히 이해하고, 각 BU의 문화와 상황을 고려하여 조직의 건강한 변화를 주도합니다. 이를 통해, 사업의 전략적 파트너로서 성장하는 경험을 할 수 있습니다.

주요업무
[주요 업무책임]
• 담당 BU의 인사 전반 프로세스 운영을 담당하며, 각 조직 리더와 구성원에게 전사 HR 정책, 제도에 대한 가이드 제공 (채용, 보상, 성과관리, 인재관리 등) 
• 담당 BU의 조직 개편, 인력 계획 및 연간 관리  
• 담당 BU의 사업목표 달성을 위한 인사관련 이슈/동향, 주요 HR 니즈를 파악하고 이를 해결하기 위한 방안 도출 및 실행  
• 담당 BU와 피플 CoE 조직 간의 가교 역할을 수행하며 효과적인 HR 정책이 수립될 수 있도록 지원 
• 구성원 경험 관리

[주요 업무환경]
• 전사 HR 및 BU의 사업 일정에 따른 업무 집중 기간 존재

자격요건
[필수 자격요건]
• 학사 이상
• 전공 무관
• 최소 5년 이상 HR 실무 경험자 혹은 3년 이상 HRBP 역할 경험자
• 비즈니스 트렌드 및 사업 전략에 대한 통찰력이 뛰어난 분
• 기본적인 노동법 및 인사 관련 법률 등에 대한 지식을 보유한 분
• 다양한 계층의 사람들과 프로페셔널 관계를 빠르게 형성하고 니즈를 파악한 경험이 있는 분
• 영어로 원활한 비즈니스 커뮤니케이션이 가능한 분
• 주요 이해관계자 (예. BU직책자, 유관부서, 경영진 등)과 적시 커뮤니케이션을 할 수 있는 분
• MS Office/Google 문서 등을 활용한 문서 작성 및 보고가 능숙한 분

우대사항
[선호 자격요건]
• 일본어, 스페인어 등 제2외국어로 커뮤니케이션이 가능한 분

[필요역량]
• 변화하는 조직구조/정책/제도/법적요건 등을 빠르게 학습할 수 있는 능력과 논리적 사고력
• 조직 내 다양한 이슈를 정확하게 해석하고 적용하며 대안을 제시하는 문제해결력
• 가이드라인 전달, 협상, 컨설팅, 상담 등 상황에 맞는 효과적 커뮤니케이션 스킬
• 업무상 습득한 정보에 대한 보안을 유지할 수 있는 높은 수준의 직업윤리와 신중한 성격

