직무 Summary 

담당 BU의 사업목표 달성을 위해 전사 HR 정책과 담당 BU를 연계하여 통합적 관점에서 채용, 온보딩, 보상, 성과관리, 인재관리, 변화관리 등 구성원 life cycle 전반에 걸친 인사제도를 실행합니다. 
BU 사업에 대한 깊이 있는 이해를 바탕으로, BU와 전사 이해관계자(경영진, 피플 조직)의 다양한 니즈를 조율하며 최적의 HR 솔루션을 제안합니다.
특히, 다양한 사업BU의 복합 포트폴리오(대형/신규BU)를 담당하며,리더십 레벨과 긴밀히 협력하여 복잡한 이해관계자 환경 속에서 Senior HR Partner로서 조직 변화를 주도하고 사업의 전략적 HR 파트너로서의 영향력을 발휘합니다.

