[쏘카에서 프로덕트 ​디자이너는 ​어떤 ​사람인가요?]
• 쏘카는 단순한 ​차량 공유 서비스가 아닙니다. ​예약·결제·차량 ​제어·위치 데이터가 ​실시간으로 맞물리고, 온라인 ​화면과 오프라인 ​차량 ​경험이 하나로 ​이어지는 ​모빌리티 ​플랫폼입니다. 고객이 차를 ​찾고, ​타고, 반납하는 모든 ​맥락에서 ​문제가 ​발생하고, 그 경험의 ​책임은 그대로 ​제품 ​설계로 돌아옵니다.
• 이런 ​제품 위에서 ​쏘카의 ​프로덕트 디자이너는 기획서를 ​화면으로 옮기거나 ​UI를 예쁘게 다듬는 사람이 아닙니다. 고객의 문제를 가장 앞에 두고, 그 이면의 진짜 문제를 짚어내고, 해결책을 끝까지 만들어내는 사람입니다.
• 문제 해결을 가로막는 것이 있다면 직무 경계를 넘습니다. 사용자 행동을 봐야 하면 직접 데이터를 뽑고, 가설을 검증해야 하면 테스트를 설계하고, 구현이 막히면 엔지니어 옆에서 함께 디테일을 만듭니다. 하나의 경험을 End-to-End로 소유합니다.
• 그리고 그 모든 과정을 AI 에이전트와 함께 합니다. AI 시대의 디자인은 화면을 잘 그리는 능력만으로 정의되지 않습니다. "어떤 문제를 어떻게 풀 것인가"를 결정하는 능력과, AI 에이전트를 손발처럼 부려 그 결정을 빠르게 탐색·검증·실행하는 능력입니다. 쏘카는 이 두 가지를 매일의 업무에서 단련하고, 비즈니스 임팩트로 증명할 수 있는 환경을 만들고 있습니다.

주요업무
[담당하시게 될 업무를 소개합니다]
1) 제품 문제 영역의 owner로서 일합니다. 
• 기능 정의 단계에서 "무엇을 왜 만들어야 하는가"를 적극적으로 제안하고, 결정한 방향을 끝까지 만들어냅니다. 주어진 요구사항을 화면으로 옮기기보다, 솔루션을 함께 도출합니다.
2) 하나의 경험을 끝까지 책임집니다. 
• 문제 정의 ＞ 설계 ＞ 출시 ＞ 결과 ＞ 학습 ＞  next 준비. 한 조각의 제품 경험이 한 사람 안에서 완성됩니다.
3) 직무의 경계를 넘나듭니다. 
• UX 리서치와 사용자 경험 설계를 책임지고, 데이터 분석(Bigquery, Amplitude 등)과 가설수립, 프로토타입 구현, ABT실험설계, 정책의 보완까지 필요하다면 제품의  디테일까지 문제 해결에 필요한 영역으로 손을 뻗습니다.
4) PM·엔지니어와 함께 문제를 풉니다. 
• 한 문제를 함께 해결하는 팀으로서, 필요한 자리에서 적극적으로 협업하며 기능을 함께 정의하고 솔루션을 함께 설계합니다. 디자이너는 화면만 그리는 것이 아니라 유저의 문제를 UX로 푸는 사람입니다.
5) AI 에이전트를 손에 들고 일합니다. 
• 리서치 정리, 디자인 탐색, 데이터 분석, UI설계, 프로토타이핑을 AI 에이전트와 처리하고, 에이전트가 잘 동작하는 조건과 한계를 자기 언어로 설명할 수 있을 만큼 깊이 다룹니다. 반복되는 작업은 스킬·자동화로 만들어 팀의 표준으로 올립니다.

자격요건
[이런 분과 함께 성장하고 싶습니다]
1) UI/UX에 전문성이 있으신 분
• 좋은 UX와 나쁜 UX를 자기 기준으로 판단할 수 있는 분
• 사용성을 지키면서도 App/Web UI를 구성할 수 있는 분
• 다양한 고객 상황을 이해/공감하고 단순 명료하게 문제를 풀어낼 수 있는 분
2) 기능 정의 단계부터 함께 고민해본 경험이 있는 분 
• 요구사항을 받아서 화면으로 옮기는 사람이 아니라, ''무엇을 왜 만들어야 하는가''를 PM·엔지니어와 함께 결정해본 분
• 문제 원인을 파악하고 뾰족한 가설이 담긴 화면을 제안하고 논리적으로 커뮤니케이션할 수 있는 분
3) AI 에이전트를 업무에 깊이 통합해본 분
• 단순히 ''AI를 써봤다'' 수준이 아니라, AI 에이전트(예: Claude, Codex, Figma make 등)의 작동 방식·강점·한계를 체득하• 고 자기 워크플로우의 일부로 만든 분. AI 없이 일하던 방식으로 돌아가는 것이 부자연스럽게 느껴지는 분
4) 자기 일을 결과로 설명할 수 있는 분 
"설계했습니다"가 아니라 "이 문제를 해결했고 어떤 결과(지표)를 만들었습니다"로 설명할 수 있는 분

우대사항
[이런 분이면 더욱 좋습니다]
• 제품 디자인 경험 7년 이상
• 복잡한 도메인에서 서비스를 설계해본 경험 - 카셰어링, 숙박/여행, 커머스 등 상품전시·예약·결제·실시간 트랜잭션 같은 O2O 도메인을 다뤄본 경험
• 기존 방식을 의심하고 새로 시도해본 경험 - 팀이 일하는  방식, 제품이 작동하는방식, 시장이 굴러가는 방식을 다르게 제안하고 실제로 바꿔본 분
• AI Native 조직 만들기에 동참하고 싶은 분 - SOCAR를 "AI 없이는 작동하지 않는 회사"로 함께 바꿔가는 여정에 흥미를 느끼는 분
• 스타트업 또는 사내 스타트업 환경에서 0 ＞ 1 제품 출시 경험

