[회사 소개]
차세대 플랫폼으로 편리함 을 넘어 무한한 가능성을 찾아 진화하고 있는 "커넥트웨이브"입니다.
커넥트웨이브는 고객과 셀러의 연결성 강화를 위해 다양한 플랫폼을 인수합병(M&A) 하여 성장해 왔습니다. 빅데이터를 기반으로 한 컨슈머 커머스(다나와, 에누리), 쇼핑몰 구축부터 연동, 운영 등 원스톱 서비스가 가능한 셀러 커머스(메이크샵, 플레이오토, 링크프라이스, 스윗트래커, 빌트온), 글로벌 풀필먼트 서비스가 강점인 크로스보더 커머스(몰테일)를 선보이며 일상 속 편리한 토탈 플랫폼으로 거듭나고 있습니다.

[근무 환경]
1. 우리 기획팀이 지향하는 AI-Native 근무 환경에 대해 소개해요.
2. 서비스기획 부서는 보고용 형식 작업(PPT 꾸미기 등)에 드는 시간을 줄이고, AI와 협업해 가설을 빠르게 검증하는 ''AI-Native 조직''으로 전환하고 있어요.
3. 기획 본연의 가치인 ''문제 정의''에 온전히 몰입할 수 있도록 인프라를 전폭 지원해요.
• Claude Max 전원 기본 지급: 최고 사양의 AI 공식 계정을 개인별로 제공해요.
• Notion 기반의 유연한 협업: 무거운 형식의 보고서 대신 Notion을 중심으로 아이디어를 빠르게 동기화(Sync)해요. 문서화 자체는 여전히 중요하게 생각하며, 형식이 아닌 내용에 집중해요.
• 열린 태도 우선: AI 툴을 이미 완벽하게 다루는 분보다, 새로운 도구로 일하는 방식을 함께 혁신해 나갈 ''열린 태도''를 가진 분을 기다립니다!

