‍‍ 함께하게 ​될 ​CS팀을 ​소개합니다!
• CS Team은 ​고객이 마키나락스의 AI 플랫폼과 ​AI ​서비스를 안정적으로 ​사용할 수 있도록 ​기술적으로 지원하는 ​조직입니다.
고객이 ​운영 중인 ​AI ​플랫폼, ​데이터 파이프라인, AI ​모델 ​및 AI 애플리케이션에서 ​발생하는 ​문의와 ​장애를 가장 먼저 ​확인하고, 엔지니어링 ​관점에서 ​문제의 원인과 ​영향을 분석합니다.
• 단순히 ​고객의 ​요청을 접수하고 전달하는 ​데 그치지 ​않습니다. 로그, 시스템 상태, 데이터 흐름, 모델 결과 등을 직접 확인하여 해결 가능한 문제는 신속하게 조치하고, 제품 개선이나 전문적인 기술 검토가 필요한 문제는 원인을 구조화하여 Product, Platform, FDE, AI Engineering 등 전담 조직에 인계합니다.
• 특정 기술 하나를 깊게 다루는 것보다 다양한 기술과 시스템을 빠르게 이해하고, 익숙하지 않은 문제라도 끝까지 원인을 찾아 해결하는 역량이 중요한 팀입니다.
• 고객의 목소리와 운영 현장의 문제를 가장 가까이에서 확인하며, 고객 경험과 마키나락스 제품 및 서비스의 안정성을 함께 높여갑니다.

주요업무
• 고객이 접수한 기술문의, 오류 및 장애 현상을 확인하고 문제를 구체적으로 정의합니다.
• 고객 환경에 구축된 마키나락스의 AI 플랫폼과 관련 서비스의 운영 상태를 확인합니다.
• 접수된 문제를 플랫폼, 인프라, 애플리케이션, 데이터, AI 모델 및 고객 환경 문제로 분류합니다.
• 고객별 유지보수 계획에 따라 AI 플랫폼과 AI 서비스의 정기점검을 수행합니다.
• 반복적으로 발생하는 문의와 장애 유형을 FAQ, Troubleshooting Guide 및 운영 매뉴얼로 정리합니다.

자격요건
• 기업 고객을 대상으로 시스템 유지보수, SM, Technical Support 또는 CS 엔지니어 업무를 5년 이상 수행한 경험이 있는 분
• Linux 환경에서 로그, 프로세스, 네트워크 및 시스템 자원의 상태를 확인할 수 있는 분
• 애플리케이션, 데이터베이스, 네트워크 및 인프라 사이에서 문제가 발생한 구간을 구분할 수 있는 분
• SQL을 활용하여 데이터와 시스템 상태를 확인할 수 있는 분
• 소프트웨어 배포 및 운영 과정에 대한 기본적인 이해를 보유한 분
• 본인이 해결하기 어려운 문제를 명확하게 구조화하여 전담 조직과 협업할 수 있는 분
• 문제의 접수부터 최종 해결과 고객 확인까지 책임감을 가지고 관리할 수 있는 분

특정 프로그래밍 언어, 프레임워크 또는 기술 스택의 숙련도만으로 평가하지 않습니다. 
새로운 기술을 빠르게 파악하고, 다양한 자료와 동료의 도움을 활용해 문제의 원인과 해결 방법을 찾아가는 역량을 중요하게 평가합니다.

우대사항
• 대기업 또는 중견기업의 시스템 운영 및 유지보수 프로젝트에서 SM 업무를 수행한 경험이 있는 분
