• AI/ML·MLOps·데이터 플랫폼을 구축·운영하거나, AI 모델을 실제 서비스에 배포·운영한 경험이 있는 분
• 예측, 이상탐지, 머신비전, 최적화 또는 LLM 기반 서비스의 운영 경험이 있는 분
• 폐쇄망, 망분리 및 보안 요구사항이 높은 고객 환경에서 업무를 수행한 경험이 있는 분
• ITSM, SLA, 장애·변경·문제관리 프로세스를 이해하고, 대응 매뉴얼·가이드·고객 보고서를 작성한 경험이 있는 분

