A ​backend ​engineer ​who builds ​the foundation every other ​team ​depends on.

Next ​Securities builds stable ​trading infrastructure ​and ​scalable services ​with ​a ​technology-centric mindset.

We are ​in ​the early stages ​of ​designing ​and implementing new ​platform systems, ​and ​we are ​at a ​point ​where we can ​define superior ​technical standards without the constraints of the existing structure. We are a team where engineers proactively design and complete the direction of the platform in an environment requiring high throughput, real-time data, multi-tenant reliability, and high availability.  Service Platform Team''s services sit on the critical path of every product team, therefore the quality of our design directly shapes the velocity and stability of the entire engineering organization

주요업무
· Design, development, and operation of platform services, such as notifications, market data, experimentation, the API gateway, and AI agents.
· Design and enhancement of architecture for large-scale event processing, real-time data streams and high-fan-out workloads
