· Non-disruptive deployment, real-time monitoring, and continuous improvement of the failure response system
· Standardization of service structure through event-driven architecture and reusable common modules
· Participation in establishing a long-term technology roadmap and structural design for next-generation trading infrastructure

*In the process of building a new system together, engineers stand at the center of technical decision-making and directly participate in structural design from a long-term perspective.

[Technology Stack]
