DeepAuto.ai는 ​KAIST ​AI대학원 ​교수와 연구원이 ​창립한 스타트업으로, GenAI 기술을 ​기업용 ​제품으로 전환하고 ​있습니다.

DeepAuto.ai의 비주얼 커뮤니케이션 ​디자이너는 경영진의 ​주요 ​발표 자료, ​IR·투자 ​유치 ​자료, 대내외 리포트, ​브랜드 ​콘텐츠 등 회사의 ​핵심 ​커뮤니케이션 ​전반을 책임지는 역할입니다. ​색, 형태, ​타이포그래피, ​레이아웃 등 ​시각 언어 ​전반을 ​다루며 브랜드가 가진 ​철학과 기술의 ​가치를 눈에 보이는 언어로 번역합니다. 연구·엔지니어링·비즈니스 조직과 긴밀히 협업하여 회사와 제품의 시각적 세계관을 구축하고, 이를 확장해 나갑니다.

Pre-A 단계에서 0-＞1을 함께 설계하며 빠르게 성장할 비주얼 커뮤니케이션 인턴을 찾습니다.

주요업무
• 브랜드 아이덴티티 기반의 시각 디자인 전반
    • 경영진 발표 자료 및 프레젠테이션 기획·디자인
    • IR(Investor Relations) 자료 디자인 및 투자 유치 자료, 사업 제안서 디자인
    • 사내외 리포트, 백서, 연간 보고서 등 문서형 콘텐츠 디자인
    • 리플릿, 브로슈어 등 인쇄·배포 자료 제작
    • 기업 홍보 및 디지털 콘텐츠 비주얼 제작 (홍보 영상, SNS 콘텐츠)
    • 홈페이지 디자인
• 브랜드 일관성 유지 및 확장
    • 전사 커뮤니케이션 채널(웹, 문서, 영상 등)의 시각적 톤앤매너 관리
    • 발표 자료 템플릿 및 비주얼 가이드라인 구축·운영
• 협업 및 커뮤니케이션
    • 대표이사 및 경영진과의 직접 커뮤니케이션을 통한 빠른 의사결정
    • 회사의 전략·비즈니스 방향성을 가장 먼저 접하고, 이를 시각적으로 구조화하는 경험
    • 전략기획, 경영지원, 마케팅, 프로덕트 팀 등 주요 조직과의 폭넓은 협업
    • 단순 실무 수행이 아닌, 커뮤니케이션 방향성 제안이 가능한 재량과 권한
• 업무 비중 안내
