지금껏 투자 없이 자체 매출로 성장해왔고, 3년 만에 700개 기업이 도입을 목표로 하고 있습니다.

‘노동의 경험을 바꿔 인간을 자유롭게 만든다’는 비전 아래 CS 자동화를 시작으로 반복 운영 업무 자동화를 통해 커머스 산업의 노동 경험을 바꾸고 있습니다.

졸업도, 스펙도 필요 없습니다. 대신 큰 목표를 끝까지 물고 늘어져 결국 답을 만드는 사람을 찾습니다.

20명의 작은 팀이지만, 팀원의 95%가 고려대·서울대·카이스트 출신으로 이루어져 있고, 각자 문제를 집요하게 파고들어 끝내 답을 만들어내는 ‘미치광이’들로 구성된 팀입니다.

주요업무
수백 개 기업의 노동 경험을 바꾸는 AI 제품을, 플랫폼부터 신규 제품까지 통째로 기획하고 키우는 경험
* 기업의 반복 CS·운영 업무를 사람 대신 처리하는 AI 에이전트 제품을 기획·관리하고, 실제 성능과 사용 경험을 책임집니다.
* 이 AI 에이전트들이 돌아가는 자사 핵심 플랫폼을 관리하며, 더 잘 동작하도록 개선 방향과 우선순위를 직접 정의합니다.
* 플랫폼과 제품에 필요한 신규 기능·신규 제품을 스스로 발굴해 01로 기획하고 출시합니다.
* 고객사 피드백과 실사용 데이터를 기반으로 "다음에 무엇을 만들지"를 결정하고, 엔지니어와 한 팀으로 제품 로드맵을 움직입니다.
* 향후 10년 가장 중요한 변화인 AI 에이전트의 한복판에서, AI 시대 프로덕트 오너십을 압축해서 쌓습니다.

